import{_ as a,o,c as t,a2 as i}from"./chunks/framework.BN2sqjC1.js";const u=JSON.parse('{"title":"Template e note giornaliere","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/template-note-giornaliere.md","filePath":"user-guide/template-note-giornaliere.md"}'),n={name:"user-guide/template-note-giornaliere.md"};function l(r,e,s,p,m,c){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="template-e-note-giornaliere" tabindex="-1">Template e note giornaliere <a class="header-anchor" href="#template-e-note-giornaliere" aria-label="Permalink to &quot;Template e note giornaliere&quot;">​</a></h1><h2 id="note-giornaliere" tabindex="-1">Note giornaliere <a class="header-anchor" href="#note-giornaliere" aria-label="Permalink to &quot;Note giornaliere&quot;">​</a></h2><p><em>Apri la nota giornaliera di oggi</em> crea (se manca) e apre la nota del giorno. In <em>Impostazioni → Note giornaliere e template</em> scegliete la <strong>cartella</strong>, il <strong>formato della data</strong> (es. <code>YYYY-MM-DD</code>) e il <strong>template</strong> da usare per le nuove note. <em>Nota giornaliera precedente/successiva</em> si spostano tra i giorni. Se aprite il comando da una nota che non è giornaliera, l&#39;app vi ricorda di controllare cartella e formato.</p><h2 id="template" tabindex="-1">Template <a class="header-anchor" href="#template" aria-label="Permalink to &quot;Template&quot;">​</a></h2><p>I template stanno nella cartella <code>.clarae/templates</code> del vault e sono di tre tipi: <strong>note</strong> (<code>.md</code>), <strong>disegni</strong> (<code>.excalidraw</code>) e <strong>presentazioni</strong> (<code>.marp</code>). La cartella è nascosta nell&#39;esploratore dei file: i template non compaiono tra le note, né nella ricerca o nel grafo. Si sincronizzano con il vault tra i vostri dispositivi.</p><p><strong>Creare e modificare un template</strong></p><ul><li><em>Nuovo template</em> chiede il tipo e il nome, e apre il template in una scheda.</li><li><em>Salva come template</em> fa del file aperto (nota, disegno o presentazione) un template, senza toccare l&#39;originale.</li><li><em>Modifica template</em> apre un template in una scheda, come qualunque file; da lì si rinomina o si elimina.</li><li>In <em>Impostazioni → Note giornaliere e template</em> trovate l&#39;elenco dei template del vault, con <em>Apri</em> ed <em>Elimina</em>.</li></ul><p><strong>Usare un template</strong></p><ul><li><em>Nuova nota da template</em> chiede il template e il nome, e crea la nota. <em>Nuovo disegno da template</em> e <em>Nuova presentazione da template</em> chiedono il template e creano il file con il nome consueto.</li><li><em>Applica template</em> aggiunge un template al file aperto: in una nota al cursore, in un disegno al centro della vista, in una presentazione come slide dopo quella corrente.</li><li>In <em>Impostazioni → Note giornaliere e template</em> potete scegliere il template di <strong>ogni nuova nota</strong>, di <strong>ogni nuovo disegno</strong> e di <strong>ogni nuova presentazione</strong>.</li></ul><p>I segnaposto <code>{{date}}</code>, <code>{{time}}</code> e <code>{{title}}</code> (elencati nelle Impostazioni) valgono per note e presentazioni; un disegno viene copiato così com&#39;è.</p><p><strong>Template di una versione precedente</strong></p><p>Fino alla 1.8 i template erano note di una cartella del vault (di norma <code>Templates</code>). Alla prima apertura l&#39;app chiede se spostarli in <code>.clarae/templates</code>; se rifiutate restano dove sono e continuano a funzionare, e potete spostarli più tardi con <em>Importa template dalla cartella…</em>. Una volta spostati non compaiono più tra le note e i link verso di essi non si risolvono più. Lo spostamento non è proposto per le cartelle condivise con voi né quando la cartella dei template è condivisa con altri: per i template di un gruppo c&#39;è la libreria di template distribuita dall&#39;amministratore.</p><h2 id="note-uniche" tabindex="-1">Note uniche <a class="header-anchor" href="#note-uniche" aria-label="Permalink to &quot;Note uniche&quot;">​</a></h2><p><em>Nuova nota unica</em> crea una nota con un nome basato sull&#39;orario (utile per appunti veloci a prova di collisione).</p><h2 id="unire-ed-estrarre" tabindex="-1">Unire ed estrarre <a class="header-anchor" href="#unire-ed-estrarre" aria-label="Permalink to &quot;Unire ed estrarre&quot;">​</a></h2><ul><li><em>Unisci la nota corrente in un&#39;altra nota</em>: aggiunge il contenuto, <strong>reindirizza i link</strong> e sposta la nota originale nel cestino (l&#39;app mostra un riepilogo e chiede conferma).</li><li><em>Estrai la selezione in una nuova nota</em>: sposta il testo selezionato in una nota nuova e lascia un link al suo posto.</li><li><em>Apri una nota casuale</em>: per riscoprire materiale dimenticato.</li></ul>',16)])])}const g=a(n,[["render",l]]);export{u as __pageData,g as default};
